'use strict';
window.AtlasInteractive=(()=>{
 const q=s=>document.querySelector(s),all=s=>[...document.querySelectorAll(s)];
 const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const planetOrder=['mercurio','venus','tierra','marte','jupiter','saturno','urano','neptuno'];
 const planets={mercurio:['Mercurio','El más cercano al Sol'],venus:['Venus','Tiene una atmósfera muy densa'],tierra:['Tierra','Nuestro planeta'],marte:['Marte','El planeta rojo'],jupiter:['Júpiter','El gigante gaseoso'],saturno:['Saturno','El planeta de los anillos'],urano:['Urano','Gira con una inclinación extrema'],neptuno:['Neptuno','El más lejano de los ocho']};
 const evidence=[
  {statement:'El Plan de San Luis llamó a levantarse contra la reelección de Porfirio Díaz el 20 de noviembre de 1910.',answer:'Hecho documentado',options:['Hecho documentado','Interpretación','Tradición o mito'],why:'Una fecha y un documento pueden contrastarse con fuentes históricas. La ficha de la Revolución ofrece referencias para seguir investigando.',source:'#ruta/revolucion'},
  {statement:'La Revolución Mexicana fue un solo movimiento con una sola causa y exactamente los mismos objetivos en todo el país.',answer:'Interpretación',options:['Hecho documentado','Interpretación','Tradición o mito'],why:'Es una explicación demasiado general: participaron proyectos, regiones y momentos distintos. Conviene preguntar quién lo afirma y qué evidencia usa.',source:'#ruta/revolucion'},
  {statement:'En una comunidad se conserva un relato oral sobre cómo una familia vivió el reparto de tierras.',answer:'Tradición o mito',options:['Hecho documentado','Interpretación','Tradición o mito'],why:'Un relato oral es una fuente cultural valiosa, pero debe distinguirse de un hecho comprobado y contrastarse con otros documentos.',source:'#patrimonio'},
  {statement:'Una fotografía histórica siempre muestra la realidad completa tal como ocurrió.',answer:'Interpretación',options:['Hecho documentado','Interpretación','Tradición o mito'],why:'Toda imagen tiene autor, fecha, encuadre y propósito. Observarla es el inicio: después hay que preguntar qué muestra y qué deja fuera.',source:'#misiones'}
 ];
 const gallery={
  espacio:[
   {src:'assets/saturn.webp',title:'Saturno y sus anillos',caption:'Imagen de Cassini, NASA/JPL/Space Science Institute.',prompt:'Observa: ¿qué cambia si miras primero el planeta, luego los anillos y por último el fondo? Escribe tres observaciones.'},
   {src:'assets/nebula.webp',title:'La nebulosa de Orión',caption:'Mosaico de NASA, ESA y equipo Hubble Orion Treasury; colores asignados.',prompt:'Busca regiones de luz, polvo y contraste. Explica qué preguntas nuevas te provoca la imagen.'},
   {src:'assets/earth.webp',title:'La Tierra desde el espacio',caption:'Fotografía Apollo 17, NASA, 1972.',prompt:'Identifica océanos, nubes y continentes. ¿Qué información sí ofrece la fotografía y cuál no?'}
  ],
  historia:[
   {src:'assets/revolucion-1910.webp',title:'Revolución: 1910',caption:'Recreación educativa identificada como ilustración de Atlas del Tiempo.',prompt:'Antes de interpretar una imagen, revisa su crédito. ¿Qué parte es evidencia visual y qué parte es una recreación?'},
   {src:'assets/atlas-hero.png',title:'Un atlas también cuenta historias',caption:'Ilustración de apertura de las rutas históricas de Atlas.',prompt:'Busca símbolos, personas y lugares. Formula una pregunta que necesitaría una fuente histórica para responderse.'},
   {src:'assets/segunda-guerra.webp',title:'Historia mundial',caption:'Recreación educativa para orientar la exploración de la Segunda Guerra Mundial.',prompt:'Observa sin asumir. ¿Qué información falta para ubicar el momento, el lugar y las personas representadas?'}
  ]
 };
 let state={area:'espacio',mode:'home',order:['tierra','jupiter','mercurio','saturno','venus','marte','neptuno','urano'],selected:null,planetFeedback:'',evidenceIndex:0,evidenceScore:0,evidenceAnswered:false,done:{},lensArea:'espacio'};
 function audience(){const a=document.body?.dataset.audience;return a==='profundizar'?'Adultos y universidad':a==='comprender'?'Jóvenes':'Niñez';}
 function persist(){try{localStorage.setItem('atlas-missions',JSON.stringify({done:state.done,evidenceScore:state.evidenceScore}));}catch(e){}}
 function restore(){try{const saved=JSON.parse(localStorage.getItem('atlas-missions')||'{}');state.done=saved.done||{};state.evidenceScore=Number(saved.evidenceScore)||0;}catch(e){}}
 function progress(){return Object.keys(state.done).length;}
 function shell(content){return `<div class="mission-shell"><header class="mission-header"><div><span class="science-label">RUTA ${safe(audience()).toUpperCase()}</span><h2>Elige, prueba y explica</h2><p>Cada misión termina con una evidencia, una decisión o una nueva pregunta.</p></div><div class="mission-progress"><strong>${progress()} / 3</strong><span>misiones completadas</span></div></header><nav class="mission-tabs" aria-label="Áreas de Misiones Atlas"><button data-mission-area="espacio" aria-pressed="${state.area==='espacio'}">✦ Espacio</button><button data-mission-area="historia" aria-pressed="${state.area==='historia'}">▧ Historia</button></nav>${content}</div>`}
 function home(){
  const cards=state.area==='espacio'?`<article class="mission-card mission-card-blue"><span class="mission-number">01</span><span class="science-label">PUZZLE DE ORBITAS</span><h3>Ordena el viaje por el sistema solar</h3><p>Organiza ocho planetas desde el Sol y explica qué patrón observaste.</p><button class="atlas-button" data-mission-mode="planet">Comenzar misión</button><span class="mission-status">${state.done['space-order']?'✓ Completada':'10–15 min'}</span></article><article class="mission-card"><span class="mission-number">02</span><span class="science-label">MIRA DE CERCA</span><h3>Detective de imágenes espaciales</h3><p>Amplía una imagen, separa observación de interpretación y escribe una pregunta.</p><button class="atlas-outline" data-mission-mode="lens">Abrir visor</button><span class="mission-status">Observación guiada</span></article>`:`<article class="mission-card mission-card-terracotta"><span class="mission-number">01</span><span class="science-label">DETECTIVE DE EVIDENCIAS</span><h3>Hecho, interpretación o tradición</h3><p>Clasifica afirmaciones y aprende a preguntar de dónde viene cada idea.</p><button class="atlas-button" data-mission-mode="evidence">Comenzar misión</button><span class="mission-status">${state.done['history-evidence']?'✓ Completada':'10–15 min'}</span></article><article class="mission-card"><span class="mission-number">02</span><span class="science-label">MIRA DE CERCA</span><h3>Leer una imagen histórica</h3><p>Acércate a una ilustración y descubre qué información falta para interpretarla.</p><button class="atlas-outline" data-mission-mode="lens">Abrir visor</button><span class="mission-status">Observación guiada</span></article>`;
  return shell(`<div class="mission-intro"><p class="eyebrow">MISIÓN ${state.area==='espacio'?'ESPACIO':'HISTORIA'}</p><h1>Aprender es investigar</h1><p>Elige una misión. Puedes volver después: Atlas guarda tus avances en este dispositivo.</p></div><div class="mission-grid">${cards}</div><div class="mission-challenge-note"><strong>Regla de oro:</strong> una respuesta vale más cuando puedes explicar qué evidencia te hizo elegirla.</div>`);
 }
 function planet(){
  const board=state.order.map((id,i)=>`<button class="planet-tile ${state.selected===i?'selected':''}" data-planet-index="${i}"><span>${i+1}</span><strong>${safe(planets[id][0])}</strong><small>${safe(planets[id][1])}</small></button>`).join('');
  return shell(`<button class="mission-back" data-mission-home>← Todas las misiones</button><div class="mission-intro"><p class="eyebrow">MISIÓN ESPACIO · PUZZLE</p><h1>Ordena el viaje por el sistema solar</h1><p>Haz clic en dos tarjetas para intercambiarlas. Ordénalas desde el Sol hacia afuera y después explica el patrón.</p></div><div class="mission-instructions"><span>1</span><p>Selecciona dos planetas para cambiar su lugar.</p><span>2</span><p>Presiona comprobar cuando tengas una hipótesis.</p><span>3</span><p>Lee la explicación y conéctala con el laboratorio de distancias.</p></div><div class="planet-puzzle" aria-label="Puzzle de orden de planetas">${board}</div><div class="mission-actions"><button class="atlas-button" data-check-planets>Comprobar orden</button><button class="atlas-outline" data-reset-planets>Revolver de nuevo</button><button class="text-link" data-planet-hint>Necesito una pista</button></div><p class="mission-feedback" role="status">${safe(state.planetFeedback)}</p>${state.planetFeedback.includes('correcto')?'<a class="atlas-button" href="#laboratorio/planetas">Llevar esta idea al laboratorio →</a>':''}`);
 }
 function evidenceView(){
  const item=evidence[state.evidenceIndex],choices=item.options.map((x,i)=>`<button data-evidence-choice="${i}" ${state.evidenceAnswered?'disabled':''} class="${state.evidenceAnswered&&x===item.answer?'is-correct':''}">${safe(x)}</button>`).join('');
  return shell(`<button class="mission-back" data-mission-home>← Todas las misiones</button><div class="mission-intro"><p class="eyebrow">MISIÓN HISTORIA · EVIDENCIAS</p><h1>Detective de fuentes</h1><p>Clasifica la afirmación y después revisa por qué una fuente necesita contexto.</p></div><div class="evidence-progress"><strong>Afirmación ${state.evidenceIndex+1} de ${evidence.length}</strong><progress value="${state.evidenceIndex}" max="${evidence.length}"></progress></div><blockquote class="evidence-statement">“${safe(item.statement)}”</blockquote><div class="evidence-options">${choices}</div><p class="mission-feedback" id="evidenceFeedback" role="status">${state.evidenceAnswered?safe(item.why):''}</p>${state.evidenceAnswered?`<div class="mission-source"><a href="${item.source}">Seguir investigando en Atlas →</a><button class="atlas-button" data-evidence-next>${state.evidenceIndex===evidence.length-1?'Terminar misión':'Siguiente afirmación'}</button></div>`:''}`);
 }
 function lens(){const list=gallery[state.area],cards=list.map((x,i)=>`<button class="lens-card" data-lens-open="${i}"><img src="${safe(x.src)}" alt="${safe(x.title)}"><span>${safe(x.title)}</span><small>Ampliar y observar</small></button>`).join('');return shell(`<button class="mission-back" data-mission-home>← Todas las misiones</button><div class="mission-intro"><p class="eyebrow">MISIÓN ${state.area==='espacio'?'ESPACIO':'HISTORIA'} · LECTURA VISUAL</p><h1>Mira de cerca</h1><p>Una imagen no es una respuesta completa. Amplíala, describe lo que observas y formula una pregunta que pueda investigarse.</p></div><div class="lens-gallery">${cards}</div><div class="mission-challenge-note"><strong>Rutina de observación:</strong> primero describe, luego interpreta y al final pregunta. Así evitas confundir lo que ves con lo que supones.</div>`)}
 function render(){const host=q('#missionApp');if(!host)return;host.innerHTML=state.mode==='planet'?planet():state.mode==='evidence'?evidenceView():state.mode==='lens'?lens():home();bind();}
 function bind(){all('[data-mission-area]').forEach(b=>b.onclick=()=>{state.area=b.dataset.missionArea;state.mode='home';state.lensArea=state.area;render()});all('[data-mission-mode]').forEach(b=>b.onclick=()=>{state.mode=b.dataset.missionMode;state.planetFeedback='';state.selected=null;state.evidenceIndex=0;state.evidenceAnswered=false;state.lensArea=state.area;render()});all('[data-mission-home]').forEach(b=>b.onclick=()=>{state.mode='home';render()});all('[data-planet-index]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.planetIndex);if(state.selected===null){state.selected=i;}else if(state.selected!==i){[state.order[state.selected],state.order[i]]=[state.order[i],state.order[state.selected]];state.selected=null;}render()});if(q('[data-check-planets]'))q('[data-check-planets]').onclick=checkPlanets;if(q('[data-reset-planets]'))q('[data-reset-planets]').onclick=()=>{state.order=['tierra','jupiter','mercurio','saturno','venus','marte','neptuno','urano'];state.selected=null;state.planetFeedback='';render()};if(q('[data-planet-hint]'))q('[data-planet-hint]').onclick=()=>{state.planetFeedback='Pista: empieza por Mercurio, el planeta más cercano al Sol. Después observa cómo se alternan planetas rocosos y gigantes gaseosos.';render()};all('[data-evidence-choice]').forEach(b=>b.onclick=()=>chooseEvidence(Number(b.dataset.evidenceChoice)));if(q('[data-evidence-next]'))q('[data-evidence-next]').onclick=nextEvidence;all('[data-lens-open]').forEach(b=>b.onclick=()=>openLens(gallery[state.area][Number(b.dataset.lensOpen)]));}
 function checkPlanets(){const ok=state.order.every((x,i)=>x===planetOrder[i]);if(ok){state.done['space-order']=true;state.planetFeedback='¡Orden correcto! Ahora explica por qué Mercurio está primero y qué diferencia hay entre un planeta rocoso y un gigante gaseoso.';persist();}else{const first=state.order.findIndex((x,i)=>x!==planetOrder[i]);state.planetFeedback=`Todavía no. Revisa la posición ${first+1}: prueba comparar la distancia media al Sol antes de volver a comprobar.`;}render()}
 function chooseEvidence(i){const item=evidence[state.evidenceIndex];state.evidenceAnswered=true;if(item.options[i]===item.answer){state.evidenceScore++;}if(state.evidenceIndex===evidence.length-1){state.done['history-evidence']=true;persist();}render()}
 function nextEvidence(){if(state.evidenceIndex<evidence.length-1){state.evidenceIndex++;state.evidenceAnswered=false;render();}else{state.mode='home';state.evidenceIndex=0;state.evidenceAnswered=false;render();}}
 function ensureLens(){if(q('#atlasLens'))return;document.body.insertAdjacentHTML('beforeend','<div class="atlas-lens" id="atlasLens" hidden role="dialog" aria-modal="true" aria-labelledby="lensTitle"><div class="atlas-lens-panel"><button class="atlas-lens-close" data-lens-close aria-label="Cerrar visor">×</button><p class="eyebrow">VISOR ATLAS</p><h2 id="lensTitle"></h2><div class="atlas-lens-image-wrap"><img id="lensImage" alt=""><span class="lens-crosshair" aria-hidden="true">＋</span></div><label class="lens-zoom" for="lensZoom">Acercar imagen <input id="lensZoom" type="range" min="1" max="2.4" step=".1" value="1"></label><p id="lensCaption" class="image-credit"></p><p id="lensPrompt" class="lens-prompt"></p><label class="lens-note-label" for="lensNote">Escribe una observación</label><textarea id="lensNote" rows="3" placeholder="Veo…, me pregunto…"></textarea><div class="mission-actions"><button class="atlas-button" data-save-lens-note>Guardar observación</button><button class="atlas-outline" data-lens-close>Cerrar visor</button></div><p id="lensStatus" class="mission-feedback" role="status"></p></div></div>');all('[data-lens-close]').forEach(b=>b.onclick=closeLens);q('#atlasLens').addEventListener('click',e=>{if(e.target.id==='atlasLens')closeLens()});q('#lensZoom').oninput=e=>{q('#lensImage').style.transform=`scale(${e.target.value})`};q('[data-save-lens-note]').onclick=()=>{const key='atlas-lens-'+q('#lensTitle').textContent;try{localStorage.setItem(key,q('#lensNote').value);}catch(e){}q('#lensStatus').textContent='Observación guardada en este dispositivo.';};}
 function openLens(item){ensureLens();q('#lensTitle').textContent=item.title;q('#lensImage').src=item.src;q('#lensImage').alt=item.title;q('#lensImage').style.transform='scale(1)';q('#lensZoom').value='1';q('#lensCaption').textContent=item.caption;q('#lensPrompt').textContent=item.prompt;let saved='';try{saved=localStorage.getItem('atlas-lens-'+item.title)||'';}catch(e){}q('#lensNote').value=saved;q('#lensStatus').textContent='';q('#atlasLens').hidden=false;q('#lensZoom').focus();}
 function closeLens(){const el=q('#atlasLens');if(el)el.hidden=true;}
 function init(){restore();ensureLens();render();document.addEventListener('click',e=>{const img=e.target.closest?.('img');if(!img||img.closest('#atlasLens'))return;if(img.closest('.portal,.cosmic-note,.domain-heading')){e.preventDefault();openLens({title:img.alt||'Imagen de Atlas',src:img.getAttribute('src'),caption:'Imagen disponible en Atlas. Consulta sus créditos antes de reutilizarla.',prompt:'¿Qué observas primero? Describe tres detalles antes de buscar una explicación.'});}});}
 function route(hash){if(hash==='misiones')render();}
 return {init,route,openLens};
})();
